/// then this number may vary over time in future versions (see [the
/// `num_threads()` method for details][snt]).
///
/// [snt]: ThreadPoolBuilder::num_threads()
#[inline]
pub fn current_num_threads(&self) -> usize {
    self.registry.num_threads()
}

